<?php $this->layout('default'); use Moves\Services\HelpdeskNotifier as N; use Moves\Support\CmsView as V; $all = N::inbox((int) $admin['id'], 'staff', 60); $unread = array_filter($all, static fn ($n) => $n['read_at'] === null); $only = V::queryString('aba') === 'novas'; $rows = $only ? $unread : $all;
$this->start('actions'); ?><?= V::actionButton('notifications-read', 'Marcar todas como lidas') ?><?php $this->stop(); ?>
<?= V::tabs([['/notificacoes', 'Todas', count($all), !$only], ['/notificacoes?aba=novas', 'Não lidas', count($unread), $only]], 'Notificações') ?>
<section class="cms-card"><?php if ($rows === []): ?><?= V::empty('Nenhuma notificação.') ?><?php endif; foreach ($rows as $n): ?><div class="cms-row"><div><a href="<?= V::e($n['link']) ?>"><strong><?= V::e($n['title']) ?></strong></a><br><small><?= V::date($n['created_at']) ?></small></div><?= $n['read_at'] ? '' : V::badge('info', 'Nova') ?></div><?php endforeach; ?></section>
